package cn.zhuatech.hragent.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class EmployeeCaseDecisionReleaseServiceTest{private final EmployeeCaseDecisionReleaseService s=new EmployeeCaseDecisionReleaseService();@Test void releasesControlledDecision(){var r=s.assess(new EmployeeCaseDecisionReleaseService.Request("C1",true,true,true,true,true,true,true,true,true,true,true));assertThat(r.decision()).isEqualTo(EmployeeCaseDecisionReleaseService.Decision.RELEASE);}@Test void reviewsAppealAndRetention(){var r=s.assess(new EmployeeCaseDecisionReleaseService.Request("C2",true,true,true,true,true,false,false,true,false,false,true));assertThat(r.actions()).hasSize(2);}@Test void blocksUnfairDecision(){var r=s.assess(new EmployeeCaseDecisionReleaseService.Request("C3",false,false,false,false,false,true,false,false,true,true,false));assertThat(r.blockers()).hasSize(8);}}
